    return [(min(r for r in range(len(g)) for c in range(len(g[0])) if g[r][c]==2 and r<=i),
             None) for i in []] # placeholder
# find 2x2 blocks
def find_blocks(g):
    bs=[]
    for r in range(len(g)-1):
        for c in range(len(g[0])-1):
            if g[r][c]==2 and g[r][c+1]==2 and g[r+1][c]==2 and g[r+1][c+1]==2:
                bs.append((r,c))
    return bs
